// ---------------------------------------------------------------------------
// Storage helpers
// ---------------------------------------------------------------------------
async function carregarLista(key) {
  try {
    const res = await storage.get(key);
    return res ? JSON.parse(res.value) : [];
  } catch {
    return [];
  }
}
async function salvarLista(key, lista) {
  try {
    await storage.set(key, JSON.stringify(lista));
    return true;
  } catch {
    return false;
  }
}

function valorInicial(campos) {
  const obj = {};
  campos.forEach((c) => { obj[c.id] = c.type === "multi" ? [] : ""; });
  return obj;
}

// ---------------------------------------------------------------------------
// Formulário de coleta
// ---------------------------------------------------------------------------
function Campo({ campo, valor, onChange }) {
  const base = "vd-input vd-focus";
  if (campo.type === "select") {
    return (
      <select className={base} value={valor} onChange={(e) => onChange(e.target.value)}>
        <option value="">Selecione…</option>
        {campo.options.map((o) => <option key={o} value={o}>{o}</option>)}
      </select>
    );
  }
  if (campo.type === "radio") {
    return (
      <div className="flex gap-2 flex-wrap">
        {campo.options.map((o) => (
          <button
            type="button"
            key={o}
            className="vd-chip"
            data-active={valor === o}
            style={valor === o ? { background: BRAND.verde, borderColor: BRAND.verde } : {}}
            onClick={() => onChange(o)}
          >
            {o}
          </button>
        ))}
      </div>
    );
  }
  if (campo.type === "multi") {
    const arr = Array.isArray(valor) ? valor : [];
    const toggle = (o) => onChange(arr.includes(o) ? arr.filter((x) => x !== o) : [...arr, o]);
    return (
      <div className="flex gap-2 flex-wrap">
        {campo.options.map((o) => (
          <button
            type="button"
            key={o}
            className="vd-chip"
            data-active={arr.includes(o)}
            style={arr.includes(o) ? { background: BRAND.azul, borderColor: BRAND.azul } : {}}
            onClick={() => toggle(o)}
          >
            {o}
          </button>
        ))}
      </div>
    );
  }
  if (campo.type === "textarea") {
    return <textarea className={base} rows={3} placeholder={campo.placeholder} value={valor} onChange={(e) => onChange(e.target.value)} />;
  }
  return (
    <input
      className={base}
      type={campo.type}
      placeholder={campo.placeholder}
      value={valor}
      onChange={(e) => onChange(e.target.value)}
    />
  );
}

function FormularioColeta({ onSalvo, categorias = CATEGORIAS, categoriaInicial }) {
  const [categoriaId, setCategoriaId] = useState(categoriaInicial || categorias[0].id);
  const categoria = categorias.find((c) => c.id === categoriaId);
  const campos = CAMPOS[categoriaId];
  const [passo, setPasso] = useState(0);
  const [dados, setDados] = useState(() => valorInicial(campos));
  const [enviando, setEnviando] = useState(false);
  const [sucesso, setSucesso] = useState(false);

  const porPasso = 4;
  const totalPassos = Math.ceil(campos.length / porPasso);
  const camposDoPasso = campos.slice(passo * porPasso, passo * porPasso + porPasso);

  function trocarCategoria(id) {
    setCategoriaId(id);
    setPasso(0);
    setDados(valorInicial(CAMPOS[id]));
    setSucesso(false);
  }

  function set(id, val) {
    setDados((d) => ({ ...d, [id]: val }));
  }

  async function enviar() {
    setEnviando(true);
    const registro = { ...dados, timestamp: new Date().toISOString() };
    const atual = await carregarLista(categoria.storageKey);
    const nova = [...atual, registro];
    await salvarLista(categoria.storageKey, nova);
    setEnviando(false);
    setSucesso(true);
    onSalvo?.(categoriaId, nova);
  }

  if (sucesso) {
    return (
      <div className="flex flex-col items-center justify-center text-center py-20 px-6">
        <div className="w-16 h-16 rounded-full flex items-center justify-center mb-5" style={{ background: categoria.cor }}>
          <Check color="#fff" size={30} />
        </div>
        <h3 className="vd-display text-2xl mb-2" style={{ color: BRAND.texto }}>Registro salvo</h3>
        <p className="text-sm mb-7 max-w-sm" style={{ color: BRAND.textoSuave }}>
          O cadastro de {categoria.label.toLowerCase()} entrou na base do painel. Obrigado por contribuir com o planejamento turístico de Vassouras.
        </p>
        <div className="flex gap-3">
          <button
            className="px-5 py-2.5 rounded-full text-sm font-medium text-white vd-focus"
            style={{ background: categoria.cor }}
            onClick={() => { setPasso(0); setDados(valorInicial(campos)); setSucesso(false); }}
          >
            Novo registro em {categoria.label}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div>
      {/* Seletor de categoria */}
      {categorias.length > 1 && (
        <div className="flex gap-2 flex-wrap mb-7">
          {categorias.map((c) => {
            const ativo = c.id === categoriaId;
            const Icone = c.icon;
            return (
              <button
                key={c.id}
                className="vd-chip flex items-center gap-2"
                data-active={ativo}
                style={ativo ? { background: c.cor, borderColor: c.cor } : {}}
                onClick={() => trocarCategoria(c.id)}
              >
                <Icone size={15} /> {c.label}
              </button>
            );
          })}
        </div>
      )}
      {/* Progresso */}
      <div className="flex items-center gap-1.5 mb-8">
        {Array.from({ length: totalPassos }).map((_, i) => (
          <div
            key={i}
            className="h-1.5 rounded-full flex-1"
            style={{ background: i <= passo ? categoria.cor : "rgba(247,242,231,0.18)", transition: "background .2s" }}
          />
        ))}
      </div>

      <div className="space-y-6 min-h-[280px]">
        {camposDoPasso.map((campo) => (
          <div key={campo.id}>
            <label className="block text-sm font-medium mb-2" style={{ color: BRAND.texto }}>
              {campo.label}{campo.required && <span style={{ color: categoria.cor }}> *</span>}
            </label>
            <Campo campo={campo} valor={dados[campo.id]} onChange={(v) => set(campo.id, v)} />
          </div>
        ))}
      </div>

      <div className="flex items-center justify-between mt-10 pt-6" style={{ borderTop: "1px solid rgba(247,242,231,0.14)" }}>
        <button
          className="flex items-center gap-1 text-sm font-medium px-4 py-2.5 rounded-full vd-focus disabled:opacity-30"
          style={{ color: BRAND.textoSuave }}
          disabled={passo === 0}
          onClick={() => setPasso((p) => Math.max(0, p - 1))}
        >
          <ChevronLeft size={16} /> Voltar
        </button>
        <span className="vd-mono text-xs" style={{ color: BRAND.textoSuave }}>
          Etapa {passo + 1} de {totalPassos}
        </span>
        {passo < totalPassos - 1 ? (
          <button
            className="flex items-center gap-1 text-sm font-medium px-5 py-2.5 rounded-full text-white vd-focus"
            style={{ background: categoria.cor }}
            onClick={() => setPasso((p) => Math.min(totalPassos - 1, p + 1))}
          >
            Continuar <ChevronRight size={16} />
          </button>
        ) : (
          <button
            className="flex items-center gap-1.5 text-sm font-medium px-5 py-2.5 rounded-full text-white vd-focus disabled:opacity-60"
            style={{ background: categoria.cor }}
            disabled={enviando}
            onClick={enviar}
          >
            {enviando ? "Salvando…" : <>Enviar registro <Check size={16} /></>}
          </button>
        )}
      </div>
    </div>
  );
}

